import re
from .aashell import execute_aashell_command


class RaDParamChangeFailed(Exception):
    pass


class RaDParamImproperFormat(Exception):
    pass


CHANGE_COMMAND = 'rad -m{change_type}w {param} {value}'


def _is_in_proper_format(param):
    return re.match(r'0x[a-fA-F0-9]+', param)


def change_rad_param(param, value, is_permanent=True, enb_ip='192.168.255.1', aashell_port='15007'):
    """
    Changes RaD parameter online through AaShell permanently
    :param param: parameter to change in hex format (0x###)
    :param value: value of parameter
    :param is_permanent: is parameter change done permanently
    """
    if not _is_in_proper_format(param):
        raise RaDParamImproperFormat('Given parameter not in proper hex format')

    change_type = _get_change_type(is_permanent)
    cmd = CHANGE_COMMAND.format(change_type=change_type, param=param, value=value)
    output = execute_aashell_command(cmd, enb_ip, aashell_port)

    if 'written succesfully' not in output:
        raise RaDParamChangeFailed("RaD parameter change was unsuccessful: %s" % repr(output))


def _get_change_type(is_permanent):
    if isinstance(is_permanent, bool):
        return 'p' if is_permanent else 'o'
    return 'p' if is_permanent.lower() in ("yes", "true", "t", "1") else 'o'


def create_swconfig_flag_address_list(sw_config_flags):
    """
     Creates list of Hex addresses based on @{SWCONFIG_FLAGS}
     :param sw_config_flags: List of swconfig flags in the same format as in Suite setup @{SWCONFIG_FLAGS}
     """
    sw_config_flags_addresses = []
    for key in sw_config_flags:
        sw_config_flags_addresses.append(key.split(' ', 1)[0])
    return sw_config_flags_addresses
